package com.trainflow.program;
import com.trainflow.ai.OllamaClient; import com.trainflow.shared.error.ApiError; import com.trainflow.trainer.Trainer; import com.trainflow.trainingcase.*; import com.trainflow.trainingneed.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component;
@Component public class OllamaProgramGenerationGateway implements ProgramGenerationGateway {private final OllamaClient client;private final TrainingCaseRepository cases;private final TrainingNeedRepository needs;private final String model,keepAlive;private final int maxTokens;public OllamaProgramGenerationGateway(OllamaClient c,TrainingCaseRepository cases,TrainingNeedRepository needs,@Value("${trainflow.ai.program-model}")String model,@Value("${trainflow.ai.program-keep-alive}")String keepAlive,@Value("${trainflow.ai.program-max-tokens}")int maxTokens){client=c;this.cases=cases;this.needs=needs;this.model=model;this.keepAlive=keepAlive;this.maxTokens=maxTokens;}public Map<String,Object> generate(UUID id){TrainingCase tc=cases.detailed(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_CASE_NOT_FOUND","Le dossier est introuvable."));TrainingNeed n=needs.findByTrainingCaseId(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_NEED_NOT_FOUND","Le besoin est introuvable."));Trainer t=tc.getTrainer();Map<String,Object> trainer=new LinkedHashMap<>();if(t!=null){trainer.put("name",t.getFullName());trainer.put("specialties",List.of());trainer.put("domains",List.of());trainer.put("years_of_experience",t.getYearsExperience());trainer.put("certifications",List.of());}Map<String,Object> input=new LinkedHashMap<>();input.put("theme",tc.getTheme());input.put("target_audience",n.getTargetAudience());input.put("objectives",n.getObjectives());input.put("planned_days_count",n.getPlannedDaysCount());input.put("total_duration_minutes",n.getDurationHours().multiply(java.math.BigDecimal.valueOf(60)).intValue());input.put("trainer",trainer);String prompt="Return JSON only using {title,general_objectives,prerequisites,evaluation_method,days:[{title,contents:[{title,concepts:[],methods:[],theory_minutes,practice_minutes}]}]}. Create a detailed professional training program. Input: "+input;return client.generateJson(model,prompt,keepAlive,maxTokens);}}
